# audiosense.py — Adding VocalDetector
class VocalDetector:
    """
    Classifies whether an audio take contains vocal presence (y=1) or is instrumental (y=0).
    Trained on the Jamendo / MUSDB18 singing voice detection corpus.
    """
    def __init__(self, n_features: int = 7):
        self.theta = np.zeros((n_features + 1, 1))

    def _sigmoid(self, z: np.ndarray) -> np.ndarray:
        return np.where(z >= 0, 1.0 / (1.0 + np.exp(-z)), np.exp(z) / (1.0 + np.exp(z)))

    def fit(self, X: np.ndarray, y: np.ndarray, alpha: float = 0.1, iters: int = 200):
        m = len(y)
        X_b = np.hstack([np.ones((m, 1)), X])

        for _ in range(iters):
            h = self._sigmoid(X_b @ self.theta)
            # Gradient vector has the exact same clean algebraic form as linear regression!
            gradient = (1.0 / m) * (X_b.T @ (h - y))
            self.theta -= alpha * gradient

    def predict_proba(self, X: np.ndarray) -> np.ndarray:
        X_b = np.hstack([np.ones((len(X), 1)), X])
        return self._sigmoid(X_b @ self.theta)

    def predict(self, X: np.ndarray, threshold: float = 0.5) -> np.ndarray:
        return (self.predict_proba(X) >= threshold).astype(int)

