import torch
import torch.nn as nn
import torch.optim as optim

class ProductionAudioClassifier(nn.Module):
    def __init__(self, input_dim: int = 7, hidden_dim: int = 16, num_classes: int = 4):
        super().__init__()
        self.network = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(hidden_dim, num_classes)
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.network(x)

# The PyTorch training loop
def train_pytorch_step(model, optimizer, criterion, X_batch, y_batch):
    optimizer.zero_grad()
    outputs = model(X_batch)           # 1. Forward propagation
    loss = criterion(outputs, y_batch) # 2. Compute loss J(theta)
    loss.backward()                    # 3. Backprop: computes delta & gradients
    optimizer.step()                   # 4. Simultaneous parameter update
    return loss.item()
